import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Вклад и сопровождение wiki","description":"","frontmatter":{"pageId":"developers/contributing","contentRevision":2},"headers":[],"relativePath":"ru/developers/contributing.md","filePath":"ru/developers/contributing.md"}'),r={name:"ru/developers/contributing.md"};function n(s,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="вклад-и-сопровождение-wiki" tabindex="-1">Вклад и сопровождение wiki <a class="header-anchor" href="#вклад-и-сопровождение-wiki" aria-label="Permalink to &quot;Вклад и сопровождение wiki&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Прочитай инструкции репозитория, status/diff и спецификацию области. Сохраняй чужие изменения. Здесь Astra пишет спецификации/планы и одно итоговое review, основная Sol реализует код и исправления. Для значимых изменений: согласованный дизайн → план → тесты/реализация → один итоговый обзор → проверки.</p><p>Wiki — часть готовности задачи. При изменении возможностей, ошибок поведения, config/CLI/API, установки, эксплуатации и восстановления обнови полные RU/EN статьи, навигацию и reference inventory в той же задаче. Укажи sourcePaths, подними contentRevision обеих версий и manifest; при отсутствии влияния на docs дай конкретное обоснование. Source snapshot не разрешает молча оставить устаревший перевод.</p><p>Запусти доступные проверки и отчитайся о страницах/результатах/ограничениях. Не включай секреты и внутренние handoff-заметки в опубликованный корпус. Коммит проверяет реальную Git-личность; push, PR и deploy требуют отдельного разрешения.</p><h2 id="contribution-dod" tabindex="-1">Готовность задачи включает документацию <a class="header-anchor" href="#contribution-dod" aria-label="Permalink to &quot;Готовность задачи включает документацию {#contribution-dod}&quot;">​</a></h2><p>До реализации найди feature-spec и статьи из sourcePaths manifest. Новая функция требует объяснения игроку и админу, а изменение API/config — обновления reference и источникового snapshot после ручной сверки. Не обновляй digest только ради зелёного CI.</p><p>Для каждого предметного topic сохрани вопрос RU/EN, anchor и точный источник. Проверь паритет и исходную базу drift, затем сборку/ссылки/браузер. Исключение docs-impact привязано к текущему base, hash изменённых файлов и reviewer; старое объяснение не разрешает будущий пропуск документации.</p><p>В отчёте назови страницы, выполненные команды и ограничения. Правка исходников wiki сама не разрешает deploy: Git identity, staged/secrets gate и команда пользователя остаются отдельными.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Датированные планы и результаты проверки — исторические материалы, не обещания текущей работоспособности. Релизная версия синхронизируется между Directory.Build.props, ClientInfo.Version и About.xml; protocol меняется только при несовместимости. Публикация Pages запускается вручную, не обычным push.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./testing">Тестирование и приёмка</a></li><li><a href="./localization">Локализация</a></li><li><a href="./../admins/updating">Обновление сервера и клиентов</a></li></ul>',14)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
